tion back toward the 2464-2507 area.", "Continued small overlapping bars holding roughly 2568-2640 keeps the trading-range classification intact.", "A break and close below 2436.87 would revive the bearish swing leg from opens 1789473600000-1789488000000."], "window_bars": 120}, "freshness": "current"}}, "raw": {"H1": [{"close": "2423.29", "close_time_ms": 1789487999999, "high": "2431.78", "low": "2402.03", "open": "2414.41", "open_time_ms": 1789484400000, "volume": "2240738.512"}, {"close": "2421.99", "close_time_ms": 1789491599999, "high": "2424.28", "low": "2415.14", "open": "2423.22", "open_time_ms": 1789488000000, "volume": "2248462.627"}, {"close": "2440.27", "close_time_ms": 1789495199999, "high": "2442.15", "low": "2412.47", "open": "2422.25", "open_time_ms": 1789491600000, "volume": "2279307.963"}, {"close": "2401.73", "close_time_ms": 1789498799999, "high": "2441", "low": "2358.62", "open": "2440.65", "open_time_ms": 1789495200000, "volume": "3189011.213"}, {"close": "2412.95", "close_time_ms": 1789502399999, "high": "2434.74", "low": "2399.66", "open": "2402.94", "open_time_ms": 1789498800000, "volume": "2490318.621"}, {"close": "2407", "close_time_ms": 1789505999999, "high": "2413.3", "low": "2397.58", "open": "2413.05", "open_time_ms": 1789502400000, "volume": "2342592.889"}, {"close": "2390.44", "close_time_ms": 1789509599999, "high": "2407.01", "low": "2390.01", "open": "2407.01", "open_time_ms": 1789506000000, "volume": "2166076.656"}, {"close": "2395.63", "close_time_ms": 1789513199999, "high": "2400.08", "low": "2381", "open": "2390.44", "open_time_ms": 1789509600000, "volume": "2292207.597"}, {"close": "2397.1", "close_time_ms": 1789516799999, "high": "2411.04", "low": "2395.62", "open": "2395.63", "open_time_ms": 1789513200000, "volume": "1968246.019"}, {"close": "2398.86", "close_time_ms": 1789520399999, "high": "2404.38", "low": "2396.92", "open": "2397.12", "open_time_ms": 1789516800000, "volume": "1974436.218"}, {"close": "2390.24", "close_ti